const r="ABCDEFGHJKMNPQRSTUVWXYZ23456789";function s(){const e=new Uint8Array(16);crypto.getRandomValues(e);const t=[];for(let n=0;n<16;n++)t.push(r[e[n]%r.length]);return t.map((n,o)=>o>0&&o%4===0?`-${n}`:n).join("")}function c(e){return e.replace(/-/g,"").slice(0,4)}async function i(e){const t=e.replace(/-/g,"").toUpperCase(),n=new TextEncoder().encode(t),o=await crypto.subtle.digest("SHA-256",n);return Array.from(new Uint8Array(o)).map(a=>a.toString(16).padStart(2,"0")).join("")}function p(e){return e.replace(/[-\s]/g,"").toUpperCase()}function u(e){return e.split("").map((t,n)=>n>0&&n%4===0?`-${t}`:t).join("")}export{c,u as d,s as g,i as h,p as n};
